// ❌ OLD: A runtime-driven framework. The template is compiled to a
// render function that builds a Virtual DOM tree on every update, then
// a reconciler diffs the old and new trees to compute DOM changes.
// This interpretation + diffing happens at RUNTIME.
function render(count) {
  return h('div', { class: 'counter' }, [
    h('p', {}, ['Count: ', count]), // ❌ OLD: tree built per render
    h('button', { onclick: inc }, ['+1']),
  ]);
}

// Every state change re-runs render() and diffs — the framework is
// shipped to the browser and does the work there.

// ✅ NEW: Svelte compiles the component at BUILD time into imperative
// JS. The DOM skeleton is created once; updates target only the nodes
// that depend on changed state. No Virtual DOM is shipped.

// (Simplified compiled output of: let count = $state(0); <p>{count}</p>)
let count = signal(0); // ✅ NEW: rune lowered to a signal

const p = element('p'); // ✅ NEW: direct DOM creation
const text = text('Count: ');

// ✅ NEW: a render effect updates ONLY this text node when count changes
render_effect(() => {
  set_text(text, count());
});

// The browser receives plain JS with no template interpreter and no
// reconciler — reactivity is compiled in.
